head.script:
scwin.init = function() {
    $w.executeSubmission("submission1");
}
scwin.mapchart1_onbeforemapchange = function(info) {
    if (info.newMapCode.length >= 2) {
        return false; // 지도 확장기능 사용하지 않음 
    }
}
scwin.mapchart1_onmapdatachange = function(dataListId) {
    var dataList = WebSquare.wUnit.getObjById(dataListId);
    switch (dataListId) {
        case $p.id+'dataList1':
            var data = dataList.getAllJSON();
            for (var i = 0; i < data.length; i++) {
                var municipality = d3.select("#" + this.id + "_map").select(".municipality.c" + data[i].code);
                municipality.style("fill", scwin.colorScale1(data[i].value));
            }
            break;
    }
}
scwin.trigger1_onclick = function(e) {
    $w.executeSubmission(selectbox1.getValue());
};
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(hexa) {
    var rgb = document.getElementsByClassName("municipality c31")[0].style.fill;
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color;
    }
    return rgb;
}
scwin.checkVal = function() {
    return scwin._checkRgb() == '#ff7a00';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 2. submission값을 변경하고 change data를 클릭한다.
    //2. Change the submission value and click change data.
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_itemTable_1').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1').setValue('submission2')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 변경한 submission값에 따라 MapChart가 변경된다.
    //2. The MapChart is changed according to the changed submission value.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.colorScale1 = d3.scale.linear()
    .range(["red", "yellow", "green", "turquoise", "blue"])
    .domain([0, 0.25, 0.5, 0.75, 1]);
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
